export function calculateDynamicResults(answers: Record<number, string>, stage: EducationStage): { category: string; score: number }[] {
  const scores: Record<string, number> = {
    engineering: 0,
    medical: 0,
    management: 0,
    civil_services: 0,
    defense: 0,
    it_software: 0,
    diploma: 0,
    skill_based: 0
  };

  const questions = stageQuestions[stage];

  questions.forEach((q) => {
    const answer = answers[q.id];
    if (!answer) return;
    const option = q.options.find((o) => o.value === answer);
    if (!option) return;
    option.categories.forEach((cat) => {
      scores[cat] += 10;
    });
  });

  return Object.entries(scores)
    .filter(([_, score]) => score > 0)
    .map(([category, score]) => ({ category, score }))
    .sort((a, b) => b.score - a.score);
}

export function generateAIInsights(results: { category: string; score: number }[], stage: EducationStage) {
  if (!results.length) {
    return {
      message: "We need more data to generate insights for you.",
      nextSteps: ["Complete the quiz fully."]
    };
  }

  const topCategory = results[0].category;

  let message = "";
  let nextSteps: string[] = [];

  switch(topCategory) {
    case "it_software":
      message = "You show a very strong aptitude for logical reasoning, problem-solving, and technology. An IT or Software career perfectly aligns with your analytical mindset.";
      nextSteps = stage === "after_10th" ? ["Opt for PCM in 11th.", "Start learning basic Python."] : stage === "after_12th" ? ["Prepare for JEE Main/Advanced or State CETs.", "Look into BCA or BTech degrees."] : ["Build a strong GitHub portfolio.", "Focus on LeetCode and DSA.", "Apply for SDE roles."];
      break;
    case "engineering":
      message = "Your interest in building, designing, and understanding how things work makes traditional engineering streams (Mechanical, Civil, Electronics) an excellent match.";
      nextSteps = stage === "after_10th" ? ["Choose Science (PCM).", "Participate in science fairs and robotics."] : ["Take Engineering Entrance Exams (JEE).", "Research specific engineering branches."] : ["Pursue MTech or GATE.", "Apply for core engineering firms."];
      break;
    case "medical":
      message = "You have profound empathy combined with a scientific temperament. A career in medical sciences where you can research and save lives suits you best.";
      nextSteps = stage === "after_10th" ? ["Opt for PCB in 11th.", "Start reading human anatomy basics."] : ["Prepare intensely for NEET.", "Look into alternative paths like BDS or Biotechnology."] : ["Prepare for PG medical entrance exams.", "Seek hospital residency programs."];
      break;
    case "management":
      message = "Your leadership qualities, strategic thinking, and interest in economics indicate that you will thrive in corporate environments, business operations, and management.";
      nextSteps = stage === "after_10th" ? ["Opt for Commerce in 11th.", "Join business and debate clubs."] : ["Look into BBA or BCom degrees.", "Prepare for IPMAT or similar entry exams."] : ["Prepare for CAT, GMAT, or XAT.", "Gain some entry-level corporate experience."];
      break;
    case "civil_services":
      message = "You exhibit a deep interest in society, governance, and taking on massive responsibilities. A powerful administrative role in civil services calls your name.";
      nextSteps = stage === "after_10th" ? ["Opt for Arts/Humanities or Commerce.", "Start reading daily newspapers."] : ["Choose a graduation subject you love.", "Begin reading NCERTs and current affairs."] : ["Dedicate 1-2 years to intense UPSC preparation.", "Join test series and mock interviews."];
      break;
    case "defense":
      message = "Your preference for discipline, physical action, and serving the nation indicates you belong in the honorable Armed Forces.";
      nextSteps = stage === "after_10th" ? ["Opt for PCM (preferred for Navy/Airforce).", "Maximize physical fitness."] : ["Prepare strictly for the NDA & NA Examination.", "Join NCC if possible."] : ["Prepare for CDS or AFCAT exams.", "Focus on SSB interview preparation."];
      break;
    case "diploma":
      message = "You want practical, fast-tracked, and hands-on professional learning rather than theoretical schooling. Technical diplomas are your fastest route to earning.";
      nextSteps = ["Research local Polytechnic colleges.", "Decide on a specific trade (e.g. Electrical, Mechanical).", "Prepare for state diploma entrance tests."];
      break;
    case "skill_based":
      message = "You are highly creative and value your independence. Skill-based digital careers like Design, Marketing, or Freelancing sit perfectly with your persona.";
      nextSteps = ["Build a strong online portofolio.", "Take specialized courses on Udemy or Coursera.", "Network with professionals on LinkedIn."];
      break;
    default:
      message = "Your interests are diverse! You have a multi-faceted personality that could adapt to many modern interdisciplinary roles.";
      nextSteps = ["Explore short internships.", "Talk to a career counselor.", "Keep learning new skills."];
      break;
  }

  return { message, nextSteps };
}

import { useEffect, useState } from "react";
import { DashboardLayout } from "@/components/DashboardLayout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { toast } from "sonner";
import { motion } from "framer-motion";
import { MessageSquare, Send } from "lucide-react";

interface Question {
  id: string;
  question: string;
  answer: string | null;
  created_at: string;
  answered_at: string | null;
}

export default function AskMentor() {
  const { user, userRole } = useAuth();
  const [questions, setQuestions] = useState<Question[]>([]);
  const [newQuestion, setNewQuestion] = useState("");
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  const fetchQuestions = async () => {
    if (!user) return;
    let query = supabase.from("mentor_questions").select("*").order("created_at", { ascending: false });
    if (userRole === "student") {
      query = query.eq("student_id", user.id);
    }
    const { data } = await query;
    setQuestions(data || []);
    setLoading(false);
  };

  useEffect(() => { fetchQuestions(); }, [user, userRole]);

  const submitQuestion = async () => {
    if (!newQuestion.trim() || !user) return;
    setSubmitting(true);
    const { error } = await supabase.from("mentor_questions").insert({
      student_id: user.id,
      question: newQuestion.trim(),
    });
    if (error) {
      toast.error("Failed to submit question");
    } else {
      toast.success("Question submitted!");
      setNewQuestion("");
      fetchQuestions();
    }
    setSubmitting(false);
  };

  const answerQuestion = async (qId: string, answer: string) => {
    const { error } = await supabase.from("mentor_questions").update({
      answer,
      answered_at: new Date().toISOString(),
      mentor_id: user!.id,
    }).eq("id", qId);
    if (error) toast.error("Failed to submit answer");
    else { toast.success("Answer submitted!"); fetchQuestions(); }
  };

  return (
    <DashboardLayout>
      <div className="max-w-3xl mx-auto space-y-6">
        <div>
          <h1 className="text-2xl font-bold">Ask a Mentor</h1>
          <p className="text-muted-foreground">
            {userRole === "mentor" ? "Answer student questions" : "Submit your career questions and get expert advice"}
          </p>
        </div>

        {userRole === "student" && (
          <Card>
            <CardContent className="p-4 space-y-3">
              <Textarea
                placeholder="Type your career question here..."
                value={newQuestion}
                onChange={(e) => setNewQuestion(e.target.value)}
                rows={3}
              />
              <Button onClick={submitQuestion} disabled={submitting || !newQuestion.trim()}>
                <Send className="mr-2 h-4 w-4" />
                {submitting ? "Submitting..." : "Submit Question"}
              </Button>
            </CardContent>
          </Card>
        )}

        {loading ? (
          <div className="flex justify-center py-10">
            <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
          </div>
        ) : questions.length === 0 ? (
          <Card>
            <CardContent className="py-12 text-center">
              <MessageSquare className="h-10 w-10 mx-auto text-muted-foreground mb-3" />
              <p className="text-muted-foreground">No questions yet</p>
            </CardContent>
          </Card>
        ) : (
          <div className="space-y-4">
            {questions.map((q, i) => (
              <motion.div key={q.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>
                <Card>
                  <CardContent className="p-4 space-y-3">
                    <div>
                      <p className="font-medium">{q.question}</p>
                      <p className="text-xs text-muted-foreground mt-1">
                        {new Date(q.created_at).toLocaleDateString()}
                      </p>
                    </div>
                    {q.answer ? (
                      <div className="bg-secondary/50 rounded-lg p-3">
                        <p className="text-xs font-medium text-primary mb-1">Mentor Response</p>
                        <p className="text-sm">{q.answer}</p>
                      </div>
                    ) : userRole === "mentor" ? (
                      <AnswerForm onSubmit={(answer) => answerQuestion(q.id, answer)} />
                    ) : (
                      <p className="text-xs text-muted-foreground italic">Awaiting mentor response...</p>
                    )}
                  </CardContent>
                </Card>
              </motion.div>
            ))}
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

function AnswerForm({ onSubmit }: { onSubmit: (answer: string) => void }) {
  const [answer, setAnswer] = useState("");
  return (
    <div className="space-y-2">
      <Textarea placeholder="Type your answer..." value={answer} onChange={(e) => setAnswer(e.target.value)} rows={2} />
      <Button size="sm" onClick={() => { onSubmit(answer); setAnswer(""); }} disabled={!answer.trim()}>
        Reply
      </Button>
    </div>
  );
}

